package com.termux.app.features.sessions;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

/**
 * How to start the shell of a terminal session: the executable, its arguments and the additional
 * environment variables, for the shell of a {@link TerminalProfile} and for startup automation.
 *
 * Startup commands and command notifications are set up without editing the user's dotfiles:
 * the session environment tells the shell to source an init script generated by
 * {@link SessionStartup} after its own startup files, and the init script sources the startup
 * files listed in {@link #ENV_STARTUP}:
 * - bash: {@code PROMPT_COMMAND} sources the init script at the first prompt, which then removes
 *   itself from {@code PROMPT_COMMAND}.
 * - zsh: {@code ZDOTDIR} points to a directory with a {@code .zshenv} that restores
 *   {@code ZDOTDIR}, sources the user's {@code .zshenv} and sources the init script at the first
 *   prompt.
 * - fish: the {@code --init-command} option sources the init script after the config files.
 * - sh (dash): {@code ENV} is sourced by interactive shells after the profile files.
 * The init scripts unset these variables, so they don't apply to shells started in the session.
 */
public final class SessionLaunchPlan {

    /** Colon-separated list of the startup files to source, set if there are startup commands. */
    public static final String ENV_STARTUP = "TERMUX_RE_STARTUP";
    /** The minimum duration in seconds of commands to notify about when they finish. */
    public static final String ENV_NOTIFY_AFTER = "TERMUX_RE_NOTIFY_AFTER";
    /** The name of the profile the session was started with. */
    public static final String ENV_PROFILE = "TERMUX_RE_PROFILE";

    public enum ShellType {
        BASH, ZSH, FISH, POSIX, OTHER;

        /** Get the type of the shell at {@code shellPath}. */
        @NonNull
        public static ShellType of(@NonNull String shellPath) {
            String name = shellPath.substring(shellPath.lastIndexOf('/') + 1);
            switch (name) {
                case "bash": return BASH;
                case "zsh": return ZSH;
                case "fish": return FISH;
                case "sh": case "dash": case "ash": case "ksh": case "mksh": return POSIX;
                default: return OTHER;
            }
        }
    }

    /** The paths of the files used to start sessions. */
    public static final class Paths {
        /** $PREFIX/bin. */
        @NonNull public final String binDir;
        /** The directory of the generated shell init scripts. */
        @NonNull public final String shellDir;

        public Paths(@NonNull String binDir, @NonNull String shellDir) {
            this.binDir = binDir;
            this.shellDir = shellDir;
        }

        @NonNull public String loginShellScript() { return shellDir + "/login-shell"; }
        @NonNull public String bashInit() { return shellDir + "/init.bash"; }
        @NonNull public String zshDotDir() { return shellDir + "/zsh"; }
        @NonNull public String zshInit() { return shellDir + "/init.zsh"; }
        @NonNull public String fishInit() { return shellDir + "/init.fish"; }
        @NonNull public String shInit() { return shellDir + "/init.sh"; }

        /** The command set in {@code PROMPT_COMMAND} to source the bash init script. */
        @NonNull public String bashPromptCommand() { return ". " + shellQuote(bashInit()); }
    }

    /** The executable, or {@code null} for the login shell found by TermuxSession, like normal sessions. */
    @Nullable public final String executable;
    /** The arguments, or {@code null} for none. */
    @Nullable public final String[] arguments;
    @NonNull public final HashMap<String, String> environment;
    /** The type of the shell that will run. */
    @NonNull public final ShellType shellType;

    private SessionLaunchPlan(@Nullable String executable, @Nullable String[] arguments,
                              @NonNull HashMap<String, String> environment, @NonNull ShellType shellType) {
        this.executable = executable;
        this.arguments = arguments;
        this.environment = environment;
        this.shellType = shellType;
    }

    /**
     * Create the plan.
     *
     * @param paths The paths of the files used to start sessions.
     * @param shellPath The path of the shell to run.
     * @param useLogin Start the shell with the login command like normal sessions, which is
     *                 possible if it is the default shell. Otherwise the shell is started by the
     *                 {@link Paths#loginShellScript()}, which does what login does for it.
     * @param startupFiles The startup files to source, may be empty.
     * @param notifyAfterSeconds The minimum duration of commands to notify about, or 0 to not notify.
     * @param profileName The name of the profile, or {@code null}.
     */
    @NonNull
    public static SessionLaunchPlan create(@NonNull Paths paths, @NonNull String shellPath, boolean useLogin,
                                           @NonNull List<String> startupFiles, int notifyAfterSeconds,
                                           @Nullable String profileName) {
        ShellType shellType = ShellType.of(shellPath);
        HashMap<String, String> environment = new HashMap<>();
        List<String> shellArguments = new ArrayList<>();

        if (profileName != null) environment.put(ENV_PROFILE, profileName);

        boolean notify = notifyAfterSeconds > 0 && (shellType == ShellType.BASH || shellType == ShellType.ZSH || shellType == ShellType.FISH);
        if ((!startupFiles.isEmpty() || notify) && shellType != ShellType.OTHER) {
            if (!startupFiles.isEmpty()) environment.put(ENV_STARTUP, String.join(":", startupFiles));
            if (notify) environment.put(ENV_NOTIFY_AFTER, String.valueOf(notifyAfterSeconds));
            switch (shellType) {
                case BASH:
                    environment.put("PROMPT_COMMAND", paths.bashPromptCommand());
                    break;
                case ZSH:
                    environment.put("ZDOTDIR", paths.zshDotDir());
                    break;
                case FISH:
                    shellArguments.add("--init-command");
                    shellArguments.add("source " + shellQuote(paths.fishInit()));
                    break;
                case POSIX:
                    environment.put("ENV", paths.shInit());
                    break;
                default:
                    break;
            }
        }

        if (useLogin) {
            return new SessionLaunchPlan(null, shellArguments.isEmpty() ? null : shellArguments.toArray(new String[0]),
                environment, shellType);
        }

        List<String> arguments = new ArrayList<>();
        arguments.add(paths.loginShellScript());
        arguments.add(shellPath);
        arguments.addAll(shellArguments);
        return new SessionLaunchPlan(paths.binDir + "/sh", arguments.toArray(new String[0]), environment, shellType);
    }

    /** Quote {@code value} as a single word for POSIX shells and fish. */
    @NonNull
    public static String shellQuote(@NonNull String value) {
        return "'" + value.replace("'", "'\\''") + "'";
    }

}
